def layout(key,title,body,description='',article=False):
    nav=''.join(f'<a href="{url}"'+(' aria-current="page"' if key==k else '')+f'>{label}</a>' for k,label,url in NAV)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f8f4eb"><meta name="description" content="{html.escape(description or title)}"><title>{html.escape(title)} · Nandini Thakur</title><link rel="icon" href="/assets/monogram.svg"><link rel="stylesheet" href="/style.css"><link rel="stylesheet" href="/contrast.css"><link rel="stylesheet" href="/motion.css"></head><body data-page="{key}"><a class="skip" href="#main">Skip to content</a><header class="site-header"><a class="wordmark" href="/" aria-label="Nandini Thakur home">nt<span>.</span></a><nav aria-label="Main navigation">{nav}</nav><a class="header-contact" href="mailto:{EMAIL}">Let’s talk {arrow()}</a></header><main id="main" class="{'article-main' if article else ''}">{body}</main><section class="conversation" aria-labelledby="conversation-title"><div><p class="eyebrow">YOUR TURN</p><h2 id="conversation-title">A question? A better idea?</h2><p>I have opinions. I’m also quite happy to revise them.</p></div><div class="conversation-actions"><button class="button secondary" data-contact="question">Ask me a question <span>↗</span></button><button class="button dark" data-contact="suggestion">Suggest something <span>↗</span></button></div></section><footer><a class="wordmark" href="/">nt<span>.</span></a><p>Nandini Thakur <span>·</span> Gurgaon, India</p><div><a href="https://www.linkedin.com/in/nandini-thakur-a1458b22a" target="_blank" rel="noopener noreferrer">LinkedIn ↗</a><a href="https://www.goodreads.com/user/show/192670676-nandini-thakur" target="_blank" rel="noopener noreferrer">Goodreads ↗</a><a href="https://www.instagram.com/thakurnandini0608" target="_blank" rel="noopener noreferrer">Instagram ↗</a></div><small>Independent thoughts. Views are my own.</small></footer><dialog id="contact-dialog" aria-labelledby="contact-title"><button class="close" data-close aria-label="Close dialog">×</button><p class="eyebrow">LET’S TALK</p><h2 id="contact-title">Ask me a question</h2><p id="contact-intro">Good questions are always welcome. So are book recommendations with a convincing argument.</p><form id="contact-form"><label for="message">Your message</label><textarea id="message" name="message" required minlength="3" maxlength="5000" rows="5" placeholder="Here’s what I’m thinking…"></textarea><p class="form-note">This opens your email app with a draft to {EMAIL}. You send it from there.</p><button type="submit" class="button dark">Continue in email <span>↗</span></button><button type="button" class="plain-button" id="copy-message">Copy message & email</button><p id="form-status" role="status"></p></form></dialog><script src="/script.js" defer></script><script src="/motion.js" defer></script>{'<script src="/scene.js" defer></script>' if key=='about' else ''}</body></html>'''

